dlabel D_800EF910
    /* CACC0 800EF910 */ .asciz "-1PUZZLE -1TRAINING: -0WHEN PLAYING PUZZLES, THERE ARE SEVERAL ADVANCED CONTROLLER OPTIONS AVAILABLE. -2-3-3THE -1%L% AND -1%R% BUTTONS ALLOW YOU TO -1ZOOM -1IN TOWARDS AND -1ZOOM -1OUT FROM THE BALL. -5-4-4-3YOU CAN USE THE -1%C\"% BUTTON TO START A PUZZLE OVER AGAIN. -2-4-3NOTICE THAT YOUR CURRENT PIECE IS ALWAYS A -1WILDCARD PIECE, SO YOU CAN USE IT ON ANY SHAPED PIECE. -2-4-3-3TO PASS THE LEVEL, YOU MUST REMOVE -1EVERY PIECE ON THE BALL USING THE NUMBER OF -1SLIDES AND -1DROPS ALLOWED. -5-4-4GREAT! HAVE FUN PLAYING PUZZLES!"
